{
  "name": "feathercode",
  "version": "0.1.0",
  "description": "OpenCode-style lean harness: small system prompt, cache-stable context, OpenCode compaction, build/plan modes, token instrumentation",
  "author": {
    "name": "square3ang"
  },
  "repository": "https://github.com/square3ang/feathercode",
  "license": "MIT",
  "userConfig": {
    "features": {
      "type": "string",
      "title": "Features",
      "description": "Comma list of enabled features: prompt,cache,tools,modes,agents,compact (or all / observe). Instrumentation is always on.",
      "default": "all"
    },
    "compaction_auto": {
      "type": "boolean",
      "title": "Auto compaction",
      "description": "Compact automatically when the context overflows (OpenCode compaction.auto)",
      "default": true
    },
    "compaction_prune": {
      "type": "boolean",
      "title": "Prune old tool output",
      "description": "Clear old tool outputs after each turn (OpenCode v1 prune; v2 removed it). Off by default.",
      "default": false
    },
    "keep_tokens": {
      "type": "number",
      "title": "Keep tokens",
      "description": "Newest conversation kept verbatim when compacting, in tokens (OpenCode v2 compaction.keep.tokens)",
      "default": 15000,
      "min": 0,
      "max": 200000
    },
    "compaction_buffer": {
      "type": "number",
      "title": "Compaction buffer",
      "description": "Compact when the context reaches window minus this many tokens; 0 uses OpenCode's max(10%, 16k) (OpenCode v2 compaction.buffer)",
      "default": 0,
      "min": 0,
      "max": 500000
    },
    "compaction_tail": {
      "type": "string",
      "title": "Recent context form",
      "description": "How the kept recent part is carried: text (OpenCode v2, flattened into the checkpoint) or messages (the original messages, verbatim)",
      "options": [
        "text",
        "messages"
      ],
      "default": "text"
    },
    "panel": {
      "type": "boolean",
      "title": "Usage panel",
      "description": "Open the token/cache panel at session start where a UI exists",
      "default": false
    }
  }
}
